import{F as r}from"./chunks/FigureContainer.VL3Ntwlh.js";import{H as e}from"./chunks/HighLightText.D0qzB827.js";import{R as i}from"./chunks/ResourceCard.DSyPPpy0.js";import{c as o,o as d,a,b as t,d as l,e as s,w as p}from"./chunks/vitepress-theme-teek.VWKGyrHm.js";/* empty css                                                                               *//* empty css                                                             *//* empty css                                                                            */const b={class:"warning custom-block"},P=JSON.parse('{"title":"LLM：大语言模型","description":"全面梳理大语言模型的定义本质、2018-2026 发展简史、开源与闭源选型对比、通用与领域模型差异、Foundation Model 生态定位，以及涌现能力与幻觉现象的深层机理，构建 LLM 核心概念知识框架。","frontmatter":{"date":"2026-06-28T15:51:21.000Z","title":"LLM：大语言模型","aliases":["LLM","Large Language Model"],"tldr":"LLM 的本质是巨大的概率分布函数 P(tokenₙ | token₁, ..., tokenₙ₋₁)，通过大规模预训练获得涌现能力，是当前 AI 产业的基石架构。","description":"全面梳理大语言模型的定义本质、2018-2026 发展简史、开源与闭源选型对比、通用与领域模型差异、Foundation Model 生态定位，以及涌现能力与幻觉现象的深层机理，构建 LLM 核心概念知识框架。","tags":["概念","LLM","基础模型","涌现","幻觉"],"categories":["大模型基础","核心概念"],"permalink":"/llm-basic/llm-concept"},"headers":[],"relativePath":"llm-basic/llm-concept.md","filePath":"22.大模型基础/02.核心概念/01.LLM大语言模型.md"}'),g={name:"llm-basic/llm-concept.md"},A=Object.assign(g,{setup(u){return(c,n)=>(d(),o("div",null,[n[14]||(n[14]=a("h1",{id:"llm-大语言模型",tabindex:"-1"},[s("LLM：大语言模型 "),a("a",{class:"header-anchor",href:"#llm-大语言模型","aria-label":"Permalink to “LLM：大语言模型”"},"​")],-1)),n[15]||(n[15]=a("blockquote",null,[a("p",null,[a("strong",null,"摘要"),s(": 大语言模型（LLM）是当前 AI 产业的核心基础设施，其本质为基于 Transformer 架构、以自回归方式建模文本概率分布的超大规模神经网络。本文从定义与特征出发，溯源 2018 至 2026 年的关键发展节点——从 GPT-1 的迁移学习范式到 DeepSeek-R1 的开源推理突破——并系统对比了开源与闭源模型在性能、可定制性、数据隐私与推理成本等维度的取舍。在此基础上，进一步辨析通用模型与领域模型的定位差异，阐释 Foundation Model 作为产业链分工基石的逻辑，最终深入讨论了涌现能力与幻觉这两种相伴而生的关键现象。全文构建了理解 LLM 全景的完整概念框架，为后续的模型选型与技术决策提供基础认知。")])],-1)),t(i,{resource:{name:"图集速览：LLM 大语言模型——概率引擎与智能的边界",description:"如果你对大语言模型（LLM）的核心概念还比较陌生，建议先读这篇图集速览。用可视化图片集合和要点摘要，帮你快速理清 LLM 的定义、发展、选型与关键现象。",url:"https://mp.weixin.qq.com/s/mOaQggUC2QkiwMzoRuJjLw",type:"article",tags:["LLM","大语言模型","涌现","幻觉"]}}),n[16]||(n[16]=l('<h2 id="_1-定义、特征与发展简史" tabindex="-1">1. 定义、特征与发展简史 <a class="header-anchor" href="#_1-定义、特征与发展简史" aria-label="Permalink to “1. 定义、特征与发展简史”">​</a></h2><h3 id="_1-1-定义与特征" tabindex="-1">1.1 定义与特征 <a class="header-anchor" href="#_1-1-定义与特征" aria-label="Permalink to “1.1 定义与特征”">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">定义</p><p>大语言模型（LLM）是通过预测下一个词的监督学习方式进行训练的，模型会根据当前输入 Context 预测下一个词的概率分布。这种<strong>以预测下一个词为训练目标的方法使得语言模型获得强大的语言生成能力。</strong></p></div>',3)),a("p",null,[n[1]||(n[1]=a("strong",null,"LLM（Large Language Model，大语言模型）",-1)),n[2]||(n[2]=s(" 是一类基于 Transformer 架构、参数量达到数十亿至数万亿的神经网络模型，其核心能力是通过 ",-1)),n[3]||(n[3]=a("strong",null,"自回归生成（Autoregressive Generation）",-1)),n[4]||(n[4]=s("：",-1)),t(e,{bold:""},{default:p(()=>[...n[0]||(n[0]=[s("逐 token 预测下一个词",-1)])]),_:1}),n[5]||(n[5]=s("，来完成文本生成、翻译、推理、代码编写等各类语言任务。",-1))]),t(r,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/llm-concept/llm_input_output.png",caption:""}),n[17]||(n[17]=l(`<p>从用户视角看，LLM 就是一个&quot;什么都会的对话机器人&quot;。但从技术视角看，LLM 的本质是：</p><blockquote><p><strong>LLM = 一个巨大的概率分布函数 P(tokenₙ | token₁, token₂, ..., tokenₙ₋₁)</strong></p></blockquote><p>即：给定前文，推理出下一个最可能出现的词元。</p><p>LLM 之所以被称为&quot;大&quot;，有四个维度的&quot;大&quot;：</p><table tabindex="0"><thead><tr><th>维度</th><th>典型数值（以 GPT-3 为例）</th><th>意义</th></tr></thead><tbody><tr><td><strong>参数量</strong></td><td>1750 亿</td><td>愈多参数，愈强的表达能力</td></tr><tr><td><strong>训练数据量</strong></td><td>~570 GB 文本（过滤后）</td><td>数据规模决定知识覆盖广度</td></tr></tbody></table><h3 id="_1-2-发展简史-2018-2026" tabindex="-1">1.2 发展简史（2018-2026） <a class="header-anchor" href="#_1-2-发展简史-2018-2026" aria-label="Permalink to “1.2 发展简史（2018-2026）”">​</a></h3><p>LLM 的发展可以用&quot;能力三跳&quot;来概括：<strong>从只能补全句子，到能听懂指令，再到能自主执行任务。</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2018 ─── GPT-1 (1.17 亿参数)</span></span>
<span class="line"><span>         ↑ 第一次证明：大模型 + 无监督预训练 + 微调 = 极强的迁移能力</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2019 ─── GPT-2 (15 亿参数)</span></span>
<span class="line"><span>         ↑ 引发争议：模型太大，太危险？OpenAI 一度拒绝开源</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2020 ─── GPT-3 (1750 亿参数)</span></span>
<span class="line"><span>         ↑ 涌现能力首次被观测！上下文学习（不用训练，给几个例子就能做新任务）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2022 ─── ChatGPT (GPT-3.5，基于 GPT-3 + RLHF)</span></span>
<span class="line"><span>         ↑ 两个月破亿用户，世界第一次感受到&quot;AI 真的来了&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2023 ─── GPT-4 / Llama 系列开源 / Claude 2</span></span>
<span class="line"><span>         ↑ GPT-4 引入多模态（图像输入）；Meta 开源 Llama 2，生态爆发</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2024 ─── Claude 3 / Llama 3 / Qwen 2.5 / DeepSeek-V2</span></span>
<span class="line"><span>         ↑ 开源卷到追赶 GPT-4；DeepSeek 用 MoE + MLA 压低成本</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2024.12 ─── DeepSeek-V3 (671B MoE, 37B activated)</span></span>
<span class="line"><span>         ↑ 训练成本仅 ~557 万美元（GPT-4 估算约 1 亿+），&quot;性价比之王&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2025 ─── DeepSeek-R1 (推理能力对齐 OpenAI o1)</span></span>
<span class="line"><span>         ↑ 第一个开源推理模型，用纯 RL（GRPO）训练出 CoT 推理能力</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2025 ─── Llama 4 / Claude 4 / Qwen 3 / Gemini 2.5</span></span>
<span class="line"><span>         ↑ 全系支持超长上下文（1M+ tokens）、多模态、工具使用、Agent 能力</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br></div></div><p><strong>关键脉络</strong>：</p><ul><li>2018-2022 是参数量的军备竞赛；</li><li>2023 至今是&quot;性价比 + 开源 + 推理能力 + Agent 能力&quot;的竞逐。</li></ul><p>规模不再是唯一指标，<strong>数据质量、推理成本、对齐质量</strong>同等重要。</p><h2 id="_2-开源-vs-闭源模型" tabindex="-1">2. 开源 vs 闭源模型 <a class="header-anchor" href="#_2-开源-vs-闭源模型" aria-label="Permalink to “2. 开源 vs 闭源模型”">​</a></h2><p>这是用户和开发者面临的第一个实际选择：</p><table tabindex="0"><thead><tr><th>对比维度</th><th>闭源模型</th><th>开源模型</th></tr></thead><tbody><tr><td><strong>代表</strong></td><td>GPT、Claude、Gemini</td><td>Llama、Qwen、DeepSeek、Mistral、Yi</td></tr><tr><td><strong>获取方式</strong></td><td>API 调用，按量付费</td><td><strong>下载权重，自己部署</strong></td></tr><tr><td><strong>性能最强</strong></td><td>通常是（GPT-5.5、Claude 4）</td><td>快速追赶，差距持续缩小</td></tr><tr><td><strong>可定制性</strong></td><td>有限（仅为微调 API）</td><td>可全量微调、修改架构、私有化部署</td></tr><tr><td><strong>数据隐私</strong></td><td>数据经过第三方服务器</td><td>全本地部署，数据不出域</td></tr><tr><td><strong>推理成本</strong></td><td>按 token 计费，高频调用昂贵</td><td>前期硬件投入大，边际成本低</td></tr><tr><td><strong>生态集成</strong></td><td>开箱即用，集成简单</td><td>需要运维能力（vLLM/Ollama 等）</td></tr></tbody></table><p><strong>2025-2026 年趋势</strong>：开源模型的推理能力已对齐闭源旗舰（如 DeepSeek-R1 对齐 OpenAI o1），选型越来越取决于<strong>部署场景</strong>而非性能差异。</p><ul><li>敏感数据（如企业内部知识库）倾向于本地部署开源模型。</li><li>对外提供服务的产品倾向于调用顶级闭源模型。</li></ul><h2 id="_3-通用模型-vs-领域模型" tabindex="-1">3. 通用模型 vs 领域模型 <a class="header-anchor" href="#_3-通用模型-vs-领域模型" aria-label="Permalink to “3. 通用模型 vs 领域模型”">​</a></h2><p><strong>通用模型</strong>（如 GPT-5、Claude）在广泛领域训练，什么都能聊，但有&quot;博而不精&quot;的问题。</p><p><strong>领域模型</strong>（如 Med-PaLM 医疗、CodeGemma 编程）专门针对垂直场景训练，在特定领域表现更优，但能力面窄。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>通用模型的知识广度 vs 领域模型的深度：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>通用模型：████████████████████████████████████████</span></span>
<span class="line"><span>         法律 ▏ 医疗 ▏ 代码 ▏ 金融 ▏ 教育 ▏ 文学 ▏ ... (广度优先)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>领域模型（医疗）：</span></span>
<span class="line"><span>         法律       医疗                   代码        ...</span></span>
<span class="line"><span>         ─         ████████████████████     ─</span></span>
<span class="line"><span>                （医疗知识深度远超通用模型）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>2025-2026 年新范式</strong>：与其从头训练领域模型，更常见的做法是 <strong>通用基础模型 + RAG（检索增强） + 领域 System Prompt</strong>。</p><p>例如：用通用 DeepSeek-V4，挂载企业内部文档库，通过 System Prompt 限定角色——这样既保留了通用模型的推理能力，又获得了领域知识的时新性和准确性。</p><h2 id="_4-foundation-model-基础模型-概念" tabindex="-1">4. Foundation Model（基础模型）概念 <a class="header-anchor" href="#_4-foundation-model-基础模型-概念" aria-label="Permalink to “4. Foundation Model（基础模型）概念”">​</a></h2><p><strong>Foundation Model（基础模型）</strong> 是 2021 年由 Stanford HAI（Human-Centered AI Institute）正式提出的术语，指代一类特征：<strong>在广泛、多样的数据上大规模预训练，可适配（Adapt）大量下游任务的基础模型。</strong></p><p>它与&quot;大语言模型&quot;的区别在于范围更大——Foundation Model 包括语言模型、视觉模型、多模态模型等。但 GPT、Claude、Llama、Qwen 等 LLM 是当前最重要的 Foundation Model。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Foundation Model 的核心逻辑：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>     ┌──────────────────────────────────────┐</span></span>
<span class="line"><span>     │        海量通用数据预训练              │</span></span>
<span class="line"><span>     │  (&quot;读遍互联网、书籍、代码、论文&quot;)      │</span></span>
<span class="line"><span>     │          成本极高，仅一次               │</span></span>
<span class="line"><span>     └──────────────────┬───────────────────┘</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>                        ▼</span></span>
<span class="line"><span>     ┌──────────────────────────────────────┐</span></span>
<span class="line"><span>     │          Foundation Model             │</span></span>
<span class="line"><span>     │   (GPT-4 / Claude / Llama / Qwen)     │</span></span>
<span class="line"><span>     │   一个模型，包含广泛的世界知识          │</span></span>
<span class="line"><span>     └──────────────────┬───────────────────┘</span></span>
<span class="line"><span>                        │</span></span>
<span class="line"><span>          ┌─────────────┼─────────────┐</span></span>
<span class="line"><span>          ▼             ▼             ▼</span></span>
<span class="line"><span>     ┌─────────┐  ┌─────────┐  ┌─────────┐</span></span>
<span class="line"><span>     │ SFT微调  │  │   RAG   │  │ Agent   │</span></span>
<span class="line"><span>     │ → 客服   │  │ → 搜索  │  │ → 自主   │</span></span>
<span class="line"><span>     │   机器人  │  │   助手  │  │   编程   │</span></span>
<span class="line"><span>     └─────────┘  └─────────┘  └─────────┘</span></span>
<span class="line"><span>     (下游适配成本极低，复用同一个 Foundation Model)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><p><strong>为什么这个概念重要？</strong> 它解释了当前 AI 产业的核心分工：</p><ul><li>少数几家做 Foundation Model 的公司在承担巨额预训练成本，而绝大多数应用层团队在&quot;如何用好 Foundation Model&quot;上创造价值——通过 Prompt Engineering、RAG、Agent、微调等方式。</li><li>理解&quot;基础模型&quot;的位置，你就理解了整个 AI 产业链的骨架。</li></ul><h2 id="_5-涌现能力" tabindex="-1">5. 涌现能力 <a class="header-anchor" href="#_5-涌现能力" aria-label="Permalink to “5. 涌现能力”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">关键理解</p><p></p><p><strong>理解涌现能力，是理解当代 AI 的核心钥匙。</strong> 它意味着我们不再是简单地给机器「编程」，而是在培育一种从前不可预期的智能形态。</p><p>这也正是为什么 AI 安全（对齐、可控性）和模型评估成为前沿方向——我们需要的不仅是更强大的模型，更是能理解其能力边界的管理手段。</p></div><p><strong>涌现能力（Emergent Abilities）</strong> 是指：当模型规模（参数量、训练数据量、计算量）<strong>越过某个临界点</strong>后，某些能力会呈现<strong>非线性的突变式增长</strong>——小模型上的表现接近随机水平，一旦规模达标则显著跃升。这些能力并非针对特定任务显式编程或微调得到的，而是模型在更大参数空间和更丰富训练数据的驱动下，<strong>被迫学会的抽象通用模式</strong>。</p>`,31)),a("p",null,[n[7]||(n[7]=s("换言之，涌现能力并非事先设计好的功能清单，而是",-1)),t(e,{bold:"",type:"note"},{default:p(()=>[...n[6]||(n[6]=[s("规模到达一定量级后，模型自发获得的更深层的智能表现",-1)])]),_:1}),n[8]||(n[8]=s('——这也是为什么"做大模型"本身就有价值：更大的规模不仅带来更低的困惑度（数学上可预测的收益），还可能解锁小模型永远无法企及的全新能力。',-1))]),n[18]||(n[18]=l('<p><strong>涌现能力的典型表现：</strong></p><table tabindex="0"><thead><tr><th>能力</th><th>描述</th><th>代表例子</th></tr></thead><tbody><tr><td><strong>上下文学习</strong> <br><strong>In-Context Learning</strong></td><td>无需微调，仅靠提示中的几个示例就能学会新任务</td><td>给两个翻译示例，模型就能自动对新句子做同类翻译</td></tr><tr><td><strong>思维链推理</strong> <br><strong>CoT</strong></td><td>加一句「让我们一步步思考」，模型自动拆解多步推理</td><td>数学应用题、逻辑谜题、复杂决策分析</td></tr><tr><td><strong>代码生成与理解</strong></td><td>根据自然语言描述生成可运行的代码，或解释一段代码的逻辑</td><td>从零写一个完整的 Web API、定位 Bug 并给出修复</td></tr><tr><td><strong>工具使用</strong></td><td>理解外部工具的调用方式，自主决定何时以及如何使用工具</td><td>调用搜索引擎查资料、调用计算器做精确计算</td></tr><tr><td><strong>多语言迁移</strong></td><td>用英语训练为主的模型，居然能理解和生成高质量中文</td><td>LLaMA 英文预训练，却能做中文问答</td></tr><tr><td><strong>校准与自我评估</strong></td><td>模型知道「自己不知道」，能评估自己回答的置信度</td><td>主动说「这个我不确定」「建议你再确认一下」</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">为什么会涌现？——几种主流解释</p><ol><li><strong>规模假说（Scaling Hypothesis）</strong>：足够大的参数空间包含了各种潜在的能力模式，只是小模型没有足够的容量去「激活」它们。参数量每翻 10 倍，可表达的复杂度就上升一个台阶</li><li><strong>数据多样性驱动</strong>：当训练数据覆盖了足够多类型的文本（论文、代码、对话、百科、小说），模型被迫学会更抽象的通用能力来统一处理所有这些任务</li><li><strong>复合任务分解</strong>：大模型在内部可能把复杂任务自动拆解为多层简单子任务，每层承担一部分计算——这种层次化处理只有足够深的网络才能实现</li><li><strong>梯度相变（Grokking）</strong>：有些能力需要训练得非常「过火」才会显现——训练损失早已不降，但验证集上的某种能力突然在某个时刻从随机水平跳到接近完美</li></ol></div><div class="warning custom-block github-alert"><p class="custom-block-title">关于涌现的争议与开放问题</p><p></p><ul><li><strong>涌现是否真实存在？</strong> 有研究者认为「涌现」只是评估指标造成的错觉——如果用更连续的指标（如 token 级别的概率校准）而非粗糙的正确/错误二分类，能力的增长曲线可能一直是平滑的，只是非线性而已</li><li><strong>缩放何时停止？</strong> Scaling Law 显示模型越大损失越低，但推理成本也指数级增长。有没有一个最优规模？还是「更大永远更好」？</li><li><strong>能力 vs 幻觉</strong>：更大的模型善于推理，但也会更自信地输出错误的答案（幻觉）。涌现能力带来的不仅是更聪明，还有更难被察觉的错误</li></ul></div><h2 id="_6-幻觉" tabindex="-1">6. 幻觉 <a class="header-anchor" href="#_6-幻觉" aria-label="Permalink to “6. 幻觉”">​</a></h2><p><strong>幻觉（Hallucination）</strong> 是指 LLM 生成的内容<strong>看似合理、语句流畅，但与事实不符或无法被验证</strong>。它是 LLM 最核心的缺陷之一，与涌现能力相伴而生——更大的模型虽然推理更强，但也会更自信地输出错误信息。</p><p><strong>幻觉的典型表现：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>描述</th><th>例子</th></tr></thead><tbody><tr><td><strong>事实性幻觉</strong></td><td>编造不存在的人、事、物</td><td>「根据 2024 年《自然》杂志的一项研究……」——实际这篇论文不存在</td></tr><tr><td><strong>忠实性幻觉</strong></td><td>回答偏离了用户提供的上下文</td><td>给模型一篇关于苹果的文章，它却开始谈梨子的营养价值</td></tr><tr><td><strong>逻辑性幻觉</strong></td><td>推理过程看似合理，但结论与前提矛盾</td><td>计算过程每一步都对，但最后给出的答案完全错误</td></tr><tr><td><strong>来源捏造</strong></td><td>编造引用、链接、论文标题</td><td>「这篇论文发表于 2023 年 NeurIPS……」——论文和年份都是编的</td></tr></tbody></table>',8)),a("div",b,[n[11]||(n[11]=a("p",{class:"custom-block-title"},"为什么会产生幻觉？",-1)),t(e,{bold:"",type:"info"},{default:p(()=>[...n[9]||(n[9]=[s("幻觉不是 bug，而是 LLM 工作原理的必然产物",-1)])]),_:1}),n[12]||(n[12]=s("。根本原因在于：",-1)),t(e,{bold:"",type:"note"},{default:p(()=>[...n[10]||(n[10]=[s("LLM 本质上是一个概率生成器，而不是一个知识库",-1)])]),_:1}),n[13]||(n[13]=l("。<ol><li><strong>训练目标决定它&quot;不追求真相&quot;</strong>：LLM 被训练来预测下一个 token 的概率，目标是让输出看起来像人写的文本，而非确保事实正确。模型没有「这是真的吗？」的判断能力</li><li><strong>知识边界不明确</strong>：模型不知道「自己不知道什么」。当被问到超出知识范围的问题时，它不会说「我不知道」，而是凭概率生成一个「看起来合理」的回答</li><li><strong>训练数据的噪声</strong>：互联网训练语料本身就包含大量错误信息、过时知识、偏见观点。模型不加区分地学到了这些</li><li><strong>概率采样引入随机性</strong>：Temperature &gt; 0 时，<strong>模型会从概率分布中采样而非永远选最高分词</strong>，这为创造性也打开了幻觉的窗口</li></ol>",2))]),n[19]||(n[19]=l('<p><strong>缓解幻觉的常见手段：</strong></p><table tabindex="0"><thead><tr><th>方法</th><th>原理</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>RAG（检索增强生成）</strong></td><td>先检索外部知识库，再用检索到的文档约束生成</td><td>需要事实准确性的场景</td></tr><tr><td><strong>Grounding（事实校准）</strong></td><td>要求模型引用来验证其输出</td><td>企业知识问答、研究辅助</td></tr><tr><td><strong>思维链提示（CoT）</strong></td><td>让模型展示推理步骤，降低跳跃性幻觉</td><td>数学、逻辑任务</td></tr><tr><td><strong>事实性微调（RLHF/DPO）</strong></td><td>用人类偏好数据训练模型偏好真实的回答</td><td>对话类产品</td></tr><tr><td><strong>置信度校准</strong></td><td>让模型输出概率 + 不确定度评估</td><td>高风险决策场景</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">幻觉与涌现是一枚硬币的两面</p><p></p><p>涌现能力让 LLM 变得强大——它能推理、创造、跨领域迁移。但幻觉提醒我们：<strong>LLM 对事实没有内在的忠诚度</strong>。它不是在回答你的问题，而是在给你一段「听起来像正确答案」的文本。理解这一点，就理解了一眼使用 LLM 的基本原则——<strong>永远不要不加验证地信任它的输出</strong>。</p></div>',3))]))}});export{P as __pageData,A as default};
